import sys
sys.stdout.reconfigure(encoding='utf-8')

with open('COS1101_Gemini_Labs/labs/exam_pseudocode.html', 'r', encoding='utf-8') as f:
    html = f.read()

# 1. Update Portal Buttons
btn_old = '<button onclick="startRealExam()" class="px-5 py-2.5 rounded-lg bg-rose-500 hover:bg-rose-600 text-white font-medium text-sm transition-colors flex items-center gap-2 shadow-sm shadow-rose-500/20">'

btn_new = """<button onclick="startRealExamSelected()" class="px-5 py-2.5 rounded-lg bg-orange-500 hover:bg-orange-600 text-white font-medium text-sm transition-colors flex items-center gap-2 shadow-sm shadow-orange-500/20">
                                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/><path d="M12 18v-6"/><path d="m9 15 3 3 3-3"/></svg>
                                สอบจริง (ข้อที่เลือก)
                            </button>
                            <button onclick="startRealExamRandom()" class="px-5 py-2.5 rounded-lg bg-rose-500 hover:bg-rose-600 text-white font-medium text-sm transition-colors flex items-center gap-2 shadow-sm shadow-rose-500/20">"""
html = html.replace(btn_old, btn_new)
html = html.replace('สอบจริง (จับเวลา)', 'สอบจริงแบบสุ่ม (5 ข้อ)')


# 2. Add Summary Screen UI right after the Editor Container
editor_end = html.find('</div>\n                </div>\n            </div>\n        </div>\n    </main>')
if editor_end == -1:
    editor_end = html.rfind('</main>') - 14

summary_ui = """
                <!-- Summary Screen -->
                <div id="summary-screen" style="display: none;" class="bg-white dark:bg-[#1e1f20] rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm mb-6 flex flex-col gap-6">
                    <div class="border-b border-slate-200 dark:border-slate-800 pb-4 text-center">
                        <h2 class="text-3xl font-bold text-slate-800 dark:text-white flex items-center justify-center gap-3">
                            <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-emerald-500"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
                            สรุปผลการสอบ
                        </h2>
                        <p class="text-lg font-medium text-slate-500 dark:text-slate-400 mt-2">คะแนนรวมของคุณ: <span id="summary-total-score" class="text-emerald-500 font-bold text-2xl">0</span> / 100</p>
                        <p class="text-xs text-slate-400 mt-1">*คะแนนประเมินด้วยระบบ AI เบื้องต้นจากการเปรียบเทียบโค้ด</p>
                    </div>
                    <div id="summary-questions" class="space-y-6"></div>
                    <div class="text-center mt-4">
                        <button onclick="exitExam()" class="px-8 py-3 rounded-full bg-slate-200 hover:bg-slate-300 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-700 dark:text-slate-200 font-bold transition-colors">
                            กลับหน้าหลัก
                        </button>
                    </div>
                </div>
"""
html = html[:editor_end] + summary_ui + html[editor_end:]


# 3. Replace all logic inside the script tag
logic_start = html.find('// ================= EXAM SYSTEM LOGIC =================')
logic_end = html.rfind('setTimeout(initExamSystem, 100);') + 32

new_logic = """// ================= EXAM SYSTEM LOGIC =================
        let currentQuestion = null;
        let timerInterval = null;
        let secondsElapsed = 0;
        let examMode = ''; // 'practice', 'solution', 'exam_selected', 'exam_random'
        let examDuration = 60 * 60; // 60 minutes

        let randomExamState = {
            active: false,
            questions: [],
            currentIndex: 0,
            userCodes: []
        };

        function initExamSystem() {
            const examSelect = document.getElementById('exam-select');
            if (typeof examDatabase !== 'undefined') {
                examDatabase.forEach((exam, i) => {
                    const option = document.createElement('option');
                    option.value = i;
                    option.textContent = exam.name;
                    examSelect.appendChild(option);
                });
            }
        }

        function onExamChange() {
            const eIdx = document.getElementById('exam-select').value;
            const qSelect = document.getElementById('question-select');
            const display = document.getElementById('problem-display');

            qSelect.innerHTML = '<option value="">-- กรุณาเลือกข้อ --</option>';
            display.classList.add('hidden');

            if (eIdx === "") {
                qSelect.disabled = true;
                return;
            }

            qSelect.disabled = false;
            examDatabase[eIdx].questions.forEach((q, i) => {
                const opt = document.createElement('option');
                opt.value = i;
                opt.textContent = `ข้อ ${i+1}`;
                qSelect.appendChild(opt);
            });
        }

        function onQuestionChange() {
            const eIdx = document.getElementById('exam-select').value;
            const qIdx = document.getElementById('question-select').value;
            const display = document.getElementById('problem-display');

            if (eIdx === "" || qIdx === "") {
                display.classList.add('hidden');
                return;
            }

            currentQuestion = examDatabase[eIdx].questions[qIdx];
            document.getElementById('problem-text').textContent = currentQuestion.problem;
            display.classList.remove('hidden');
        }

        function updateTimerDisplay() {
            if (examMode === 'solution') {
                document.getElementById('timer-display').parentElement.style.display = 'none';
                return;
            } else {
                document.getElementById('timer-display').parentElement.style.display = 'block';
            }

            let s = examMode === 'practice' ? secondsElapsed : Math.max(0, examDuration - secondsElapsed);
            let mins = Math.floor(s / 60).toString().padStart(2, '0');
            let secs = (s % 60).toString().padStart(2, '0');
            document.getElementById('timer-display').textContent = `${mins}:${secs}`;

            if (examMode.startsWith('exam') && s <= 0) {
                clearInterval(timerInterval);
                alert("หมดเวลาทำข้อสอบแล้ว! ระบบจะทำการส่งข้อสอบอัตโนมัติ");
                submitExam(true);
            }
        }

        function startTimer() {
            clearInterval(timerInterval);
            if (examMode !== 'exam_random' || randomExamState.currentIndex === 0) {
                secondsElapsed = 0; // Only reset if not moving to next random question
            }
            updateTimerDisplay();
            timerInterval = setInterval(() => {
                secondsElapsed++;
                updateTimerDisplay();
            }, 1000);
        }

        function setupEditorUI(mode) {
            document.getElementById('exam-portal').style.display = 'none';
            document.getElementById('summary-screen').style.display = 'none';
            document.getElementById('exam-status-bar').classList.remove('hidden');
            document.getElementById('editor-container').style.display = 'grid'; 

            const eIdx = document.getElementById('exam-select').value;
            const qIdx = document.getElementById('question-select').value;

            let displayTitle = '';

            if (mode === 'exam_random') {
                 let qData = randomExamState.questions[randomExamState.currentIndex];
                 currentQuestion = qData.q;
                 displayTitle = `แบบทดสอบสุ่ม (${randomExamState.currentIndex + 1}/5) - ${qData.name}`;
            } else {
                 displayTitle = `${examDatabase[eIdx].name} - ข้อ ${parseInt(qIdx)+1}`;
                 currentQuestion = examDatabase[eIdx].questions[qIdx];
            }

            document.getElementById('output').innerHTML = '<div class="text-center text-slate-500 mt-10">หน้าจอแสดงผลลัพธ์</div>';
            document.getElementById('status-exam-name').textContent = displayTitle;
            document.getElementById('active-problem-text').textContent = currentQuestion.problem;

            const btnRun = document.getElementById('btn-run-code');
            const btnSubmit = document.getElementById('btn-submit-exam');
            const outputPanel = document.getElementById('panel-monitor');

            examMode = mode;

            if (mode === 'practice' || mode === 'solution') {
                document.getElementById('status-mode-label').textContent = mode === 'practice' ? 'โหมดทดลองทำ' : 'โหมดดูเฉลย';
                document.getElementById('status-mode-label').className = 'text-xs font-bold uppercase tracking-wide text-emerald-500';
                document.getElementById('timer-label').textContent = 'เวลาที่ใช้';

                btnRun.style.display = 'flex';
                btnSubmit.style.display = 'none';
                outputPanel.style.opacity = '1';
                outputPanel.style.pointerEvents = 'auto';

            } else if (mode.startsWith('exam')) {
                document.getElementById('status-mode-label').textContent = mode === 'exam_random' ? 'สอบจริง (สุ่ม 5 ข้อ)' : 'สอบจริง (ข้อที่เลือก)';
                document.getElementById('status-mode-label').className = 'text-xs font-bold uppercase tracking-wide text-rose-500';
                document.getElementById('timer-label').textContent = 'เวลาที่เหลือ';

                btnRun.style.display = 'none';
                btnSubmit.style.display = 'flex';

                if (mode === 'exam_random') {
                    btnSubmit.innerHTML = randomExamState.currentIndex < 4 ? 'ส่งคำตอบข้อนี้ (ถัดไป)' : 'ส่งข้อสอบทั้งหมด';
                } else {
                    btnSubmit.innerHTML = 'ส่งข้อสอบ';
                }

                outputPanel.style.opacity = '0.7'; 
                outputPanel.style.pointerEvents = 'none';
            }
        }

        function viewSolution() {
            if (!document.getElementById('exam-select').value) return;
            setupEditorUI('solution');
            document.getElementById('code').value = currentQuestion.solution || "Function Main\\n\\nEnd";
            updateEditor();
            startTimer();
        }

        function startPractice() {
            if (!document.getElementById('exam-select').value) return;
            setupEditorUI('practice');
            document.getElementById('code').value = "Function Main\\n\\nEnd";
            updateEditor();
            startTimer();
        }

        function startRealExamSelected() {
            if (!document.getElementById('exam-select').value) return;
            if (confirm("คำเตือน: คุณกำลังเข้าสู่โหมดสอบจริง!\\n\\n- จับเวลา 60 นาที\\n- ไม่สามารถรันโค้ดเพื่อดูผลลัพธ์ได้\\n- ต้องกด 'ส่งข้อสอบ' เมื่อทำเสร็จ\\n\\nพร้อมหรือไม่?")) {
                randomExamState.active = false;
                setupEditorUI('exam_selected');
                document.getElementById('code').value = "Function Main\\n\\nEnd";
                updateEditor();
                startTimer();
            }
        }

        function startRealExamRandom() {
            if (confirm("คำเตือน: คุณกำลังเข้าสู่โหมดสุ่มทดสอบ 5 ข้อ!\\n\\n- สุ่มข้อสอบ 5 ข้อให้ทำต่อเนื่อง\\n- จับเวลา 60 นาทีรวมทั้งหมด\\n- ไม่สามารถรันโค้ดเพื่อดูผลลัพธ์ได้\\n- เมื่อจบจะสรุปคะแนนประเมินให้\\n\\nพร้อมหรือไม่?")) {
                let allQs = [];
                examDatabase.forEach(e => e.questions.forEach(q => allQs.push({q: q, name: e.name})));

                // Shuffle array
                for (let i = allQs.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [allQs[i], allQs[j]] = [allQs[j], allQs[i]];
                }

                randomExamState.active = true;
                randomExamState.questions = allQs.slice(0, 5);
                randomExamState.currentIndex = 0;
                randomExamState.userCodes = [];

                setupEditorUI('exam_random');
                document.getElementById('code').value = "Function Main\\n\\nEnd";
                updateEditor();
                startTimer();
            }
        }

        function calculateMockScore(userCode, solCode) {
            if (!userCode || userCode.trim() === 'Function Main\\n\\nEnd') return 0;
            let solTokens = solCode.toLowerCase().match(/[a-z0-9_\\[\\]]+/g) || [];
            let userTokens = userCode.toLowerCase().match(/[a-z0-9_\\[\\]]+/g) || [];
            let ignore = ['function', 'main', 'end', 'declare', 'integer', 'string', 'real', 'output', 'input', 'assign', 'if', 'else', 'while', 'for', 'to'];
            solTokens = solTokens.filter(t => !ignore.includes(t));

            if (solTokens.length === 0) return 20; 

            let matchCount = 0;
            solTokens.forEach(t => { if (userTokens.includes(t)) matchCount++; });

            let percentage = Math.min(100, (matchCount / solTokens.length) * 100);
            return Math.round((percentage / 100) * 20); 
        }

        function finishRandomExam() {
            clearInterval(timerInterval);
            document.getElementById('exam-status-bar').classList.add('hidden');
            document.getElementById('editor-container').style.display = 'none';

            const summaryDiv = document.getElementById('summary-screen');
            const qList = document.getElementById('summary-questions');
            summaryDiv.style.display = 'flex';

            let totalScore = 0;
            let html = '';

            randomExamState.questions.forEach((qData, i) => {
                let uCode = randomExamState.userCodes[i] || '';
                let sCode = qData.q.solution || '';
                let score = calculateMockScore(uCode, sCode);
                totalScore += score;

                html += `
                <div class="bg-slate-50 dark:bg-[#131314] rounded-xl p-4 border border-slate-200 dark:border-slate-800">
                    <div class="flex justify-between items-center mb-2">
                        <h4 class="font-bold text-slate-800 dark:text-slate-200">ข้อที่ ${i+1}: ${qData.name}</h4>
                        <span class="px-3 py-1 bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-400 rounded-lg font-bold text-sm">ได้ ${score} / 20 คะแนน</span>
                    </div>
                    <p class="text-sm text-slate-600 dark:text-slate-400 mb-4">${qData.q.problem}</p>
                    <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <span class="text-xs font-bold text-slate-500 uppercase">โค้ดที่คุณเขียน</span>
                            <pre class="mt-1 p-3 bg-white dark:bg-[#1e1f20] rounded border border-slate-200 dark:border-slate-700 text-xs overflow-x-auto">${uCode.replace(/</g, '&lt;')}</pre>
                        </div>
                        <div>
                            <span class="text-xs font-bold text-slate-500 uppercase">โค้ดเฉลย</span>
                            <pre class="mt-1 p-3 bg-emerald-50 dark:bg-emerald-900/10 rounded border border-emerald-200 dark:border-emerald-800/30 text-xs text-emerald-800 dark:text-emerald-400 overflow-x-auto">${sCode.replace(/</g, '&lt;')}</pre>
                        </div>
                    </div>
                </div>`;
            });

            qList.innerHTML = html;
            document.getElementById('summary-total-score').textContent = totalScore;
        }

        function submitExam(auto = false) {
            let uCode = document.getElementById('code').value;

            if (examMode === 'exam_random') {
                if (auto || confirm(randomExamState.currentIndex < 4 ? "ยืนยันส่งคำตอบข้อนี้และไปข้อถัดไป?" : "ยืนยันส่งข้อสอบทั้งหมด?")) {
                    randomExamState.userCodes.push(uCode);
                    if (randomExamState.currentIndex < 4) {
                        randomExamState.currentIndex++;
                        setupEditorUI('exam_random');
                        document.getElementById('code').value = "Function Main\\n\\nEnd";
                        updateEditor();
                    } else {
                        finishRandomExam();
                    }
                }
            } else {
                if (auto || confirm("คุณแน่ใจหรือไม่ว่าต้องการส่งข้อสอบ? ระบบจะหยุดเวลาทันที")) {
                    clearInterval(timerInterval);
                    alert("ส่งข้อสอบเรียบร้อยแล้ว!");
                    exitExam();
                }
            }
        }

        function exitExam() {
            if (examMode.startsWith('exam') && document.getElementById('summary-screen').style.display !== 'flex') {
                if (!confirm("กำลังทำการสอบ! ต้องการยกเลิกและกลับไปหน้าหลักหรือไม่? โค้ดที่พิมพ์ไว้จะหายไป")) return;
            }
            clearInterval(timerInterval);
            document.getElementById('exam-portal').style.display = 'flex';
            document.getElementById('exam-status-bar').classList.add('hidden');
            document.getElementById('editor-container').style.display = 'none';
            document.getElementById('summary-screen').style.display = 'none';

            randomExamState.active = false;
            onQuestionChange(); // Resync portal UI to dropdown
        }

        setTimeout(initExamSystem, 100);\n"""

html = html[:logic_start] + new_logic + html[logic_end:]

with open('COS1101_Gemini_Labs/labs/exam_pseudocode.html', 'w', encoding='utf-8') as f:
    f.write(html)
