target_logic = 'function finishRandomExam() {'
feedback_logic = """
        function generateFeedback(userCode, solCode) {
            let feedback = [];
            let uLower = userCode.toLowerCase();
            let sLower = solCode.toLowerCase();

            // 1. Check basic structure
            if (!uLower.includes('function main') || !uLower.includes('end')) {
                feedback.push('❌ โค้ดของคุณขาดโครงสร้างเริ่มต้น (Function Main / End)');
            }

            // 2. Extract and check variable declarations
            let sVars = [];
            let declareMatches = sLower.match(/declare\\s+(integer|real|string)\\s+([a-z0-9_, \\[\\]]+)/g);
            if (declareMatches) {
                declareMatches.forEach(d => {
                    let vars = d.replace(/declare\\s+(integer|real|string)\\s+/, '').split(',');
                    vars.forEach(v => {
                        let vName = v.trim().split('[')[0]; // remove array brackets
                        if(vName) sVars.push(vName);
                    });
                });
            }

            let missingVars = [];
            sVars.forEach(v => {
                // Check if user declared this variable or at least used it
                let regex = new RegExp(`\\\\b${v}\\\\b`, 'i');
                if (!regex.test(uLower)) {
                    missingVars.push(v);
                }
            });

            if (missingVars.length > 0 && missingVars.length <= 5) {
                feedback.push(`⚠️ ดูเหมือนคุณจะไม่ได้ใช้/ประกาศตัวแปรสำคัญ: <code>${missingVars.join(', ')}</code> (หรืออาจใช้ชื่ออื่นแทน)`);
            } else if (missingVars.length > 5) {
                feedback.push(`❌ โค้ดของคุณมีโครงสร้างตัวแปรต่างจากเฉลยค่อนข้างมาก (อาจตีความโจทย์ผิด หรือยังไม่ได้เริ่มทำ)`);
            } else if (sVars.length > 0) {
                feedback.push(`✅ คุณมีการใช้ตัวแปรสำคัญได้ครบถ้วนตามแนวทางของเฉลย`);
            }

            // 3. Check loops
            let sHasFor = sLower.includes('for ');
            let sHasWhile = sLower.includes('while ');
            let uHasFor = uLower.includes('for ');
            let uHasWhile = uLower.includes('while ') || uLower.includes('do');

            if (sHasFor && !uHasFor) feedback.push(`⚠️ เฉลยใช้ <code>For Loop</code> แต่คุณไม่ได้ใช้ (อาจทำให้การวนซ้ำตามจำนวนรอบที่แน่นอนทำงานผิดพลาด)`);
            if (sHasWhile && !uHasWhile) feedback.push(`⚠️ เฉลยใช้ <code>While Loop</code> สำหรับการวนซ้ำแบบมีเงื่อนไข แต่คุณไม่ได้ใช้`);
            if (!sHasFor && !sHasWhile && (uHasFor || uHasWhile)) feedback.push(`⚠️ โจทย์ข้อนี้ไม่จำเป็นต้องใช้ Loop แต่โค้ดของคุณมีการวนซ้ำ`);

            // 4. Check Arrays
            if (sLower.includes('[') && sLower.includes(']')) {
                if (!uLower.includes('[')) {
                    feedback.push(`❌ โจทย์ข้อนี้มีการใช้ <b>Array (อาร์เรย์)</b> แต่คุณยังไม่ได้ประกาศหรือใช้งาน Array เลย`);
                }
            }

            // 5. Conditionals
            let sHasIf = sLower.includes('if ');
            let uHasIf = uLower.includes('if ');
            if (sHasIf && !uHasIf) {
                feedback.push(`❌ โค้ดของคุณขาดการตรวจสอบเงื่อนไข (<code>If...Then</code>) ที่โจทย์ต้องการ`);
            }

            // 6. Outputs
            let sOutCount = (sLower.match(/output /g) || []).length;
            let uOutCount = (uLower.match(/output /g) || []).length;
            if (sOutCount > 0 && uOutCount === 0) {
                feedback.push(`❌ คุณลืมเขียนคำสั่ง <code>Output</code> เพื่อแสดงผลลัพธ์`);
            } else if (sOutCount > uOutCount + 2) {
                feedback.push(`⚠️ คุณมีการแสดงผล (<code>Output</code>) น้อยกว่าเฉลย อาจแสดงข้อความหรือผลลัพธ์ไม่ครบ`);
            }

            // Generate HTML
            if (feedback.length === 0) {
                feedback.push(`✨ โค้ดของคุณมีโครงสร้างยอดเยี่ยมและสอดคล้องกับเฉลยมาก!`);
            }

            let html = '<ul class="space-y-2 mt-2">';
            feedback.forEach(f => {
                html += `<li class="text-sm text-slate-700 dark:text-slate-300 bg-slate-100 dark:bg-[#2a2b2c] p-2 rounded">${f}</li>`;
            });
            html += '</ul>';
            return html;
        }

        function finishRandomExam() {"""

html = html.replace(target_logic, feedback_logic)

# Then, modify finishRandomExam to inject the feedback
html = html.replace("""<div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div>
                            <span class="text-xs font-bold text-slate-500 uppercase">โค้ดที่คุณเขียน</span>""",
